ALTER TABLE "seat_holds" DROP CONSTRAINT "hold_state";--> statement-breakpoint
ALTER TABLE "seat_holds" ADD CONSTRAINT "hold_state" CHECK (("seat_holds"."status" IN ('ACTIVE','CONVERTED') AND "seat_holds"."released_at" IS NULL AND "seat_holds"."expired_at" IS NULL) OR ("seat_holds"."status"='RELEASED' AND "seat_holds"."released_at" IS NOT NULL AND "seat_holds"."released_at">="seat_holds"."created_at" AND "seat_holds"."expired_at" IS NULL) OR ("seat_holds"."status"='EXPIRED' AND "seat_holds"."expired_at" IS NOT NULL AND "seat_holds"."expired_at">="seat_holds"."effective_expires_at" AND "seat_holds"."released_at" IS NULL));